def read_wordlist(path):
    try:
        with open(path) as f:
            return f.readlines()
    except FileNotFoundError:
        print(f"Wordlist {path} missing")
        raise  # still propagate so caller knows

try:
    read_wordlist("missing.txt")
except FileNotFoundError:
    print("Falling back to default wordlist")

class WeakPasswordError(Exception):
    pass

def set_password(pwd):
    if len(pwd) < 8:
        raise WeakPasswordError("Password too short!")

for attempt in ["admin", "supersecretpassword"]:
    try:
        set_password(attempt)
    except WeakPasswordError as e:
        print(f"Rejected: {e}")
    else:
        print("Accepted")
